  plannedStart?: string & { readonly __brand: 'CalendarDate' } | null;
  /**
     * Planned end, for tasks. On or after PlannedStart.
     * @nullable
     */
  plannedEnd?: string & { readonly __brand: 'CalendarDate' } | null;
  /**
     * The milestone's date. Only for milestones.
     * @nullable
     */
