/**
 * An intake desk's settings and members, overwriting what it has. Settings that do not change record nothing.
 */
export interface UpdateIntakeDeskRequest {
  /**
     * The desk being changed; must match the route.
     * @minLength 1
     */
  id: string;
  /**
     * What its members and administrators call the desk. Unique.
     * @minLength 1
     * @maxLength 128
     */
  name: string;
  /**
     * The requester-facing description of what kind of ask to bring here, which requesters choose by.
     * @minLength 1
     * @maxLength 1024
     */
  description: string;
  /**
     * How much of a request on the desk reaches people outside it: Open, SummaryOnly or Private. Only the
     * Demand Management Admin may change it.
     */
  visibility: IntakeDeskVisibility;
  /** Whether a requester can pick the desk. One they cannot is a destination agents route to. */
  isRequesterSelectable: boolean;
  /** Whether the desk accepts new requests. */
  isOpen: boolean;
  /** On a private desk, whether the requester may add participants themselves. Agents always can. */
  requesterMayAddParticipants: boolean;
  /**
     * Whether the desk offers every active company channel, including channels added later. A new desk does.
     * Leave it out to keep the desk's channels as they are.
     * @nullable
     */
  offersAllChannels?: boolean | null;
  /**
     * The company channels the desk offers when `offersAllChannels` is false; empty means the desk offers
     * none, and its submit form does not ask where a request came from. Leave it out to keep the ones it has.
     * Ignored unless `offersAllChannels` is false. A channel already chosen may stay after it is archived;
     * a newly chosen one must be active.
     * @nullable
     * @items.minLength 1
     */
  channelIds?: string[] | null;
  /**
     * Whether the desk's agents tag requests in every active company tag category, including categories added later. A
     * new desk does. Leave it out to keep the desk's categories as they are.
     * @nullable
     */
  offersAllTagCategories?: boolean | null;
  /**
     * The tag categories the desk's agents tag in when `offersAllTagCategories` is false; empty means none. Leave
     * it out to keep the ones it has. Ignored unless `offersAllTagCategories` is false. A category already chosen
     * may stay after it is deactivated; a newly chosen one must be active. Requests keep tags in any category.
     * @nullable
     * @items.minLength 1
     */
  tagCategoryIds?: string[] | null;
  /**
     * Whether the desk's agents may add free tags — tags in no category, typed in while tagging. A new desk does not.
     * Leave it out to keep the desk's setting. Requests already carrying free tags keep them when it is turned off.
     * @nullable
     */
  allowsFreeTags?: boolean | null;
  /**
     * Everyone on the desk after the change, each with their role. Naming, removing or re-roling a Desk Admin
     * needs the Demand Management Admin.
     */
  members: IntakeDeskMemberRequest[];
  /**
     * The members who triage the desk's new requests — told about requests waiting on it unassigned — after the
     * change; empty means nobody, and the desk triages from its board. Leave it out to keep the desk's triagers.
     * Each must be in `members`; a member named in this change can triage at once, and a member removed stops.
     * @nullable
     * @items.minLength 1
     */
  triagerIds?: string[] | null;
  /**
     * The desk's `revision` as it was read before making this change. A desk changed since refuses the
     * update with 409, so a stale page never undoes what someone else changed.
     */
  expectedRevision: number;
}

